// Chimera's built-in FM cart library: cart 0 is Chimera's own "Chimera Voices"; the rest are
// thousands of DX7 voices sorted into sound categories (Piano, Bass, Bells, ...) and cut into
// numbered 32-voice carts ("Bass 1", "Bass 2", ...). Plain C++, shared by every version.
// The voice data lives in FmLibraryData.cpp (generated by tools/build_fm_library.py).
#pragma once
#include "Synth/dsp/Fm.h"
#include <string>
#include <vector>

namespace el::chimera {

int fmLibCategoryCount();                    // category 0 is "Chimera" (one cart)
const char* fmLibCategoryName (int category);
int fmLibCategoryCarts (int category);       // number of carts in the category
int fmLibCategoryFirstCart (int category);   // index of its first cart

int fmLibCartCount();                        // all carts, in category order
int fmLibVoiceCount();                       // all voices in all carts
int fmLibCartCategory (int cart);
std::string fmLibCartName (int cart);        // "Chimera Voices", "Bass 12"
int fmLibFindCart (const std::string& name); // the cart with that name, or -1
std::vector<Dx7Patch> fmLibCart (int cart);  // its voices (32, fewer in a category's last cart)

namespace fmlib {   // the generated data
    struct Category { const char* name; int firstVoice; int count; };
    extern const Category kCategories[];
    extern const int kCategoryCount;
    extern const int kVoiceCount;
    extern const unsigned char kVoices[];
}

} // namespace el::chimera
